function [k] = kozai_constant(ecc, inc)
%KOZAI_CONSTANT  The Kozai constant sqrt(1 - e^2) cos(i) of an orbit's eccentricity and inclination [rad].
%   ecc: real[1] (passed a plain number)
%   inc: real[1] (passed a plain number)
%   returns k: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    k = 0;
    k = (sqrt((1 - (ecc * ecc))) * cos(inc));
end
